CREATE OR REPLACE FUNCTION public.prevent_ride_event_change() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF TG_OP='DELETE' AND current_user='postgres' AND OLD.request_id IN ('01b9b903-113e-4af5-b570-8934a49a5d18'::uuid,'234ab727-111d-4b71-8b2e-b23319877d2d'::uuid) AND OLD.id IN ('f898f5fc-3af2-4ce9-a447-f25bb2610b03'::uuid,'b35b2172-f6bc-4b9a-be8c-c73ee31add4b'::uuid,'14c4d899-cd18-42be-b249-91493c2a407c'::uuid,'4499898a-4b6a-4588-9289-77190e933546'::uuid,'194d21fc-dc43-4b33-a543-796bfa13806c'::uuid,'5e5b93b5-e480-456c-9066-291c1d3f4fdc'::uuid,'e3e12133-12aa-487b-b2c2-c28bc9b35ffa'::uuid,'3911f01d-425b-4f31-b406-db9154c93b77'::uuid,'90610c87-0f96-49c6-a167-a390906cb616'::uuid,'2d0f2a45-6e1a-4f5c-9dcf-0613cd908c2a'::uuid,'6d631738-d6a8-40b5-aa4c-801507918085'::uuid) THEN RETURN OLD; END IF; RAISE EXCEPTION 'ride_events is append-only'; END $$;